#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        // to_camel logic
        int i = 0;
        int j = 0;
        char *str = argv[2];
        char result[1000];
        while (str[i] != '\0') {
            if (str[i] == '_') {
                i++;
                result[j] = toupper(str[i]);
                j++;
            } else {
                result[j] = str[i];
                j++;
            }
            i++;
        }
        result[j] = '\0';
        printf("%s\n", result);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        // to_snake logic
        int i = 0;
        int j = 0;
        char *str = argv[2];
        char result[1000];
        while (str[i] != '\0') {
            if (isupper(str[i])) {
                if (i != 0) {
                    result[j] = '_';
                    j++;
                }
                result[j] = tolower(str[i]);
                j++;
            } else {
                result[j] = str[i];
                j++;
            }
            i++;
        }
        result[j] = '\0';
        printf("%s\n", result);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
